import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Post } from '../data/posts';
import { getPostById, votePost } from '../services/postService';
import { useAuth } from '../context/AuthContext';
import AnimatedText from './AnimatedText';
import AnimatedList from './AnimatedList';

const PostDetail: React.FC = () => {
  const { postId } = useParams<{ postId: string }>();
  const [post, setPost] = useState<Post | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { isAuthenticated } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (postId) {
      const fetchedPost = getPostById(postId);

      if (fetchedPost) {
        setPost(fetchedPost);
      } else {
        setError('Post not found');
      }

      setIsLoading(false);
    }
  }, [postId]);

  const handleVote = (increment: boolean = true) => {
    if (!postId || !post) return;

    const updatedPost = votePost(postId, increment);
    if (updatedPost) {
      setPost(updatedPost);
    }
  };

  const handleEdit = () => {
    if (postId) {
      navigate(`/post/edit/${postId}`);
    }
  };

  if (isLoading) {
    return <div className="loading">Loading...</div>;
  }

  if (error) {
    return <div className="error-message">{error}</div>;
  }

  if (!post) {
    return <div className="not-found">Post not found</div>;
  }

  const renderPostContent = () => {
    switch (post.type) {
      case 'essay':
        return (
          <div className="post-content essay-content">
            <AnimatedText text={post.content} element="p" />
          </div>
        );

      case 'movie':
        return (
          <div className="post-content movie-content">
            <div className="video-container">
              <iframe 
                src={post.videoUrl} 
                title={post.title} 
                width="560" 
                height="315" 
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              />
            </div>
            <AnimatedText text={post.description} element="p" />
          </div>
        );

      case 'image':
        return (
          <div className="post-content image-content">
            <img 
              src={post.imageUrl} 
              alt={post.title} 
              className="post-image" 
            />
            <AnimatedText text={post.description} element="p" />
          </div>
        );

      case 'carousel':
        return (
          <div className="post-content carousel-content">
            <AnimatedList staggerDelay={0.05} component="div" className="carousel-images">
              {post.images.map((image, index) => (
                <div key={index} className="carousel-item">
                  <img 
                    src={image.url} 
                    alt={image.caption} 
                    className="carousel-image"
                  />
                  <div className="caption">
                    <AnimatedText text={image.caption} />
                  </div>
                </div>
              ))}
            </AnimatedList>
          </div>
        );

      default:
        return <div>Unknown post type</div>;
    }
  };

  return (
    <div className="post-detail">
      <AnimatedList staggerDelay={0.05}>
        <h2><AnimatedText text={post.title} /></h2>

        <div className="post-meta">
          <span className="post-type">
            <AnimatedText text={`Type: ${post.type}`} />
          </span>
          <span className="post-votes">
            <AnimatedText text={`Votes: ${post.votes}`} />
          </span>
        </div>

        {renderPostContent()}

        <div className="post-actions">
          {isAuthenticated && (
            <>
              <button 
                onClick={() => handleVote(true)} 
                className="vote-button upvote"
              >
                Upvote
              </button>
              <button 
                onClick={() => handleVote(false)} 
                className="vote-button downvote"
              >
                Downvote
              </button>
              <button 
                onClick={handleEdit} 
                className="edit-button"
              >
                Edit Post
              </button>
            </>
          )}
          <button 
            onClick={() => navigate(-1)} 
            className="back-button"
          >
            Back
          </button>
        </div>
      </AnimatedList>
    </div>
  );
};

export default PostDetail;
